////////////////////////////////////////////////////////////////////////////
// push_decoder_test.c
//
// Tests for the persistent push WavPack decoder. The fixed driver calls
// push_cases() once per group: "fragment", "correction", "flow",
// "terminal". Audio is generated by the library's own encoder and every
// decoded integer is compared against the legacy full-file entry point.
////////////////////////////////////////////////////////////////////////////

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "wavpack.h"
#include "checks.h"

typedef struct { unsigned char *p; size_t n, pos, visible; } Bytes;

static int block_append (void *id, void *data, int32_t n)
{
    Bytes *b = (Bytes *) id;
    unsigned char *q = (unsigned char *) realloc (b->p, b->n + (size_t) n);
    if (!q) return 0;
    b->p = q;
    memcpy (q + b->n, data, (size_t) n);
    b->n += (size_t) n;
    return 1;
}

static int32_t block_read (void *id, void *out, int32_t want)
{
    Bytes *b = (Bytes *) id;
    size_t n = (size_t) want;
    if (n > b->visible - b->pos) n = b->visible - b->pos;
    memcpy (out, b->p + b->pos, n);
    b->pos += n;
    return (int32_t) n;
}

static int64_t block_get_pos (void *id) { return (int64_t) ((Bytes *) id)->pos; }
static int block_seek_abs (void *id, int64_t p) { (void) id; (void) p; return -1; }
static int block_seek_rel (void *id, int64_t p, int m) { (void) id; (void) p; (void) m; return -1; }

static int block_push_back (void *id, int c)
{
    Bytes *b = (Bytes *) id;
    if (!b->pos) return EOF;
    b->pos--;
    return c;
}

static int64_t block_length (void *id) { (void) id; return 0; }
static int block_can_seek (void *id) { (void) id; return 0; }

static WavpackStreamReader64 mem_reader = {
    block_read, NULL, block_get_pos, block_seek_abs, block_seek_rel,
    block_push_back, block_length, block_can_seek, NULL, NULL
};

// Distinct per-channel marker so a channel order or interleave mistake fails.

static void make_pcm (int32_t *pcm, int channels, int frames)
{
    for (int i = 0; i < frames; ++i)
        for (int c = 0; c < channels; ++c)
            pcm [i * channels + c] = ((i * 7919 + c * 1543 + i * i * (c + 1)) % 60001) - 30000;
}

static void encode_program (int channels, int frames, int hybrid, int unknown_length,
    Bytes *wv, Bytes *wvc, int32_t *pcm)
{
    WavpackConfig config;

    make_pcm (pcm, channels, frames);
    memset (&config, 0, sizeof (config));
    config.bits_per_sample = 16;
    config.bytes_per_sample = 2;
    config.num_channels = channels;
    config.channel_mask = (channels == 1) ? 1 : (channels == 2) ? 3 : ((1u << channels) - 1);
    config.sample_rate = 48000;
    config.block_samples = 64;

    if (hybrid) {
        config.flags = CONFIG_HYBRID_FLAG | CONFIG_CREATE_WVC;
        config.bitrate = 2.5;
    }

    WavpackContext *enc = WavpackOpenFileOutput (block_append, wv, hybrid ? wvc : NULL);
    task_check (enc != NULL, "encoder opens");
    task_check (WavpackSetConfiguration64 (enc, &config, unknown_length ? -1 : frames, NULL),
        "encoder configured");
    task_check (WavpackPackInit (enc), "pack init");
    task_check (WavpackPackSamples (enc, pcm, (uint32_t) frames), "pack samples");
    task_check (WavpackFlushSamples (enc), "flush samples");
    WavpackCloseFile (enc);
}

// Full decode through the legacy entry point: the integer-by-integer reference.

static void reference_decode (Bytes *wv, Bytes *wvc, int hybrid, int channels,
    int frames, int32_t *ref)
{
    char error [128] = {0};

    wv->pos = 0;
    wv->visible = wv->n;
    if (hybrid) { wvc->pos = 0; wvc->visible = wvc->n; }

    WavpackContext *dec = WavpackOpenFileInputEx64 (&mem_reader, wv, hybrid ? wvc : NULL,
        error, 0, 0);
    task_check (dec != NULL, "reference decoder opens");
    task_check (WavpackGetNumChannels (dec) == channels, "reference channel count");
    task_check (WavpackUnpackSamples (dec, ref, (uint32_t) frames) == (uint32_t) frames,
        "reference frame count");
    task_check (!WavpackGetNumErrors (dec), "reference has no CRC errors");
    WavpackCloseFile (dec);
}

// Offset of the end of the first complete block group (FINAL_BLOCK with audio).

static size_t first_group_end (Bytes *b)
{
    size_t p = 0;

    while (p + 32 <= b->n) {
        WavpackHeader h;
        memcpy (&h, b->p + p, sizeof (h));
        WavpackLittleEndianToNative (&h, WavpackHeaderFormat);
        task_check (!memcmp (h.ckID, "wvpk", 4), "physical header marker");
        p += (size_t) h.ckSize + 8;
        if (h.block_samples && (h.flags & FINAL_BLOCK))
            return p;
    }

    task_check (0, "complete group found");
    return 0;
}

// Drain a decoder while feeding both lanes in small chunks. Suffix bytes are
// resent using the accepted count. When reference is non-NULL every integer
// is checked; returns the number of frames delivered.

static uint64_t drain_push (WavpackPushDecoder *pd, Bytes *wv, Bytes *wvc, int hybrid,
    int channels, const int32_t *reference, int finish_lanes, const int *cap_cycle,
    int cap_cycle_len, uint64_t already)
{
    uint64_t frames = already;
    int wv_done = 0, wvc_done = 0, cycle = 0, guard = 5000000;
    int32_t *pcm = (int32_t *) malloc ((size_t) 16 * channels * sizeof (int32_t));
    task_check (pcm != NULL, "drain buffer allocated");

    for (;;) {
        task_check (--guard > 0, "drain loop terminates");

        for (int lane = 0; lane < (hybrid ? 2 : 1); ++lane) {
            Bytes *b = lane ? wvc : wv;
            int *done = lane ? &wvc_done : &wv_done;

            if (b->pos < b->n) {
                size_t remaining = b->n - b->pos;
                size_t want = remaining < 9 ? remaining : 9;
                size_t accepted = 0;
                task_check (WavpackPushFeed (pd, lane, b->p + b->pos, want, &accepted) == 0,
                    "fragment feed accepted");
                b->pos += accepted;
            }

            if (finish_lanes && b->pos == b->n && !*done) {
                *done = 1;
                task_check (WavpackPushFinish (pd, lane) == 0, "lane finish");
            }
        }

        uint32_t capacity = (uint32_t) cap_cycle [cycle++ % cap_cycle_len];
        uint32_t written = 0;
        int status = WavpackPushRead (pd, pcm, capacity, &written);

        if (status == WV_PUSH_PCM) {
            task_check (written > 0 && written <= capacity, "PCM status writes frames");

            if (reference)
                for (uint32_t i = 0; i < written; ++i)
                    for (int c = 0; c < channels; ++c)
                        task_check (pcm [i * channels + c] ==
                            reference [(frames + i) * channels + c], "exact integer PCM match");

            frames += written;
            continue;
        }

        task_check (written == 0, "non-PCM status writes nothing");

        if (status == WV_PUSH_DONE)
            break;

        task_check (status == WV_PUSH_NEED_WV || status == WV_PUSH_NEED_WVC ||
            status == WV_PUSH_NEED_OUTPUT, "waiting status while undrained");
    }

    free (pcm);
    return frames;
}

// Feed every remaining byte of both lanes one byte per Feed call, interleaved
// with capped Reads so backpressure can drain, then finish and drain to DONE.
// If overwrite_lane >= 0, each accepted byte of that lane is immediately
// clobbered, proving the decoder copied the prefix it accepted.

static uint64_t bytewise_run (WavpackPushDecoder *pd, Bytes *wv, Bytes *wvc, int hybrid,
    int channels, const int32_t *reference, int overwrite_lane)
{
    uint64_t frames = 0;
    int caps [3] = {1, 7, 3};
    int cycle = 0, guard = 10000000;
    int32_t *pcm = (int32_t *) malloc ((size_t) 16 * channels * sizeof (int32_t));
    task_check (pcm != NULL, "bytewise output buffer");

    for (;;) {
        task_check (--guard > 0, "bytewise loop terminates");
        int progress = 0;

        // one byte per lane per round; a zero-accepted byte stays at the same
        // source position and is simply resent after the Read below

        for (int lane = 0; lane < (hybrid ? 2 : 1); ++lane) {
            Bytes *b = lane ? wvc : wv;

            if (b->pos < b->n) {
                size_t accepted = 0;
                task_check (WavpackPushFeed (pd, lane, b->p + b->pos, 1, &accepted) == 0,
                    "bytewise feed succeeds");
                task_check (accepted <= 1, "bytewise accepted at most one");
                if (accepted) {
                    if (lane == overwrite_lane)
                        b->p [b->pos] = (unsigned char) (b->p [b->pos] ^ 0x5A);
                    b->pos += accepted;
                    progress = 1;
                }
            }
        }

        uint32_t capacity = (uint32_t) caps [cycle++ % 3];
        uint32_t written = 0;
        int status = WavpackPushRead (pd, pcm, capacity, &written);

        if (status == WV_PUSH_PCM) {
            task_check (written > 0, "bytewise PCM non-empty");
            for (uint32_t i = 0; i < written; ++i)
                for (int c = 0; c < channels; ++c)
                    task_check (pcm [i * channels + c] ==
                        reference [(frames + i) * channels + c], "bytewise exact PCM");
            frames += written;
            continue;
        }

        task_check (written == 0, "bytewise non-PCM writes nothing");

        int all_fed = (wv->pos == wv->n) && (!hybrid || wvc->pos == wvc->n);

        if (all_fed) {
            task_check (WavpackPushFinish (pd, 0) == 0, "bytewise wv finish");
            if (hybrid) task_check (WavpackPushFinish (pd, 1) == 0, "bytewise wvc finish");
            break;
        }

        task_check (progress || status == WV_PUSH_NEED_OUTPUT,
            "bytewise feeding makes progress or only lacks output room");
    }

    // drain whatever PCM remains after the last finish

    for (;;) {
        uint32_t written = 0;
        int status = WavpackPushRead (pd, pcm, 7, &written);
        if (status == WV_PUSH_DONE)
            break;
        task_check (status == WV_PUSH_PCM, "post-feed drain only yields PCM then DONE");
        for (uint32_t i = 0; i < written; ++i)
            for (int c = 0; c < channels; ++c)
                task_check (pcm [i * channels + c] ==
                    reference [(frames + i) * channels + c], "drain exact PCM");
        frames += written;
    }

    free (pcm);
    return frames;
}

// -------------------------------- fragment --------------------------------

static void fragment_cases (void)
{
    enum { CHANNELS = 6, FRAMES = 257 };
    int32_t pcm [FRAMES * CHANNELS], ref [FRAMES * CHANNELS];

    // Exhaustive bisection cuts run in plain lossless mode: split mechanics are
    // identical on either lane, and the hybrid path is covered bytewise below.

    {
        Bytes wv = {0}, wvc = {0};
        encode_program (CHANNELS, FRAMES, 0, 0, &wv, &wvc, pcm);
        reference_decode (&wv, &wvc, 0, CHANNELS, FRAMES, ref);

        size_t group1 = first_group_end (&wv);
        task_check (group1 >= 32, "group spans a full header");

        // Every cut of the header and the first group body: feed the prefix,
        // clobber it, then deliver the remainder strictly one byte at a time
        // from a scratch buffer that is overwritten as bytes are accepted.

        for (size_t cut = 1; cut < group1; ++cut) {
            unsigned char *scratch = (unsigned char *) malloc (wv.n);
            task_check (scratch != NULL, "scratch buffer");
            memcpy (scratch, wv.p, wv.n);
            Bytes feed = {0};
            feed.p = scratch;
            feed.n = wv.n;

            WavpackPushDecoder *pd = WavpackPushCreate (1u << 20, 0);
            task_check (pd != NULL, "push decoder created");
            size_t accepted = 0;
            task_check (WavpackPushFeed (pd, 0, scratch, cut, &accepted) == 0, "prefix feed");
            task_check (accepted == cut, "whole prefix accepted");
            memset (scratch, 0xA5, cut);       // stored copy must survive overwrite
            feed.pos = cut;

            task_check (bytewise_run (pd, &feed, &wvc, 0, CHANNELS, ref, 0) == FRAMES,
                "all frames recovered across the bisection cut");

            WavpackPushInfo info;
            task_check (WavpackPushGetInfo (pd, &info) == 1, "format known after decode");
            task_check (info.channels == CHANNELS && info.sample_rate == 48000 &&
                info.bits_per_sample == 16, "reported format matches");
            task_check (info.samples_returned == FRAMES && info.buffered_wv == 0,
                "nothing retained at end");
            WavpackPushDestroy (pd);
            free (scratch);
        }

        free (wv.p);
    }

    // Both modes: the exact 19-byte short-header cut from the baseline, plus a
    // full strictly byte-at-a-time feed with accepted-byte overwrite.

    for (int hybrid = 0; hybrid <= 1; ++hybrid) {
        Bytes wv = {0}, wvc = {0};
        encode_program (CHANNELS, FRAMES, hybrid, 0, &wv, &wvc, pcm);
        reference_decode (&wv, &wvc, hybrid, CHANNELS, FRAMES, ref);

        {
            unsigned char *swv = (unsigned char *) malloc (wv.n);
            unsigned char *swvc = NULL;
            memcpy (swv, wv.p, wv.n);
            Bytes fwv = {0}; fwv.p = swv; fwv.n = wv.n;
            Bytes fwvc = {0};
            if (hybrid) {
                swvc = (unsigned char *) malloc (wvc.n);
                memcpy (swvc, wvc.p, wvc.n);
                fwvc.p = swvc; fwvc.n = wvc.n;
            }

            WavpackPushDecoder *pd = WavpackPushCreate (1u << 20, hybrid);
            size_t accepted = 0;
            task_check (WavpackPushFeed (pd, 0, swv, 19, &accepted) == 0 && accepted == 19,
                "19-byte header prefix waits instead of failing");
            WavpackPushInfo info;
            task_check (WavpackPushGetInfo (pd, &info) == 0 && info.channels == 0,
                "format undetermined on partial header");
            memset (swv, 0xA5, 19);
            fwv.pos = 19;
            if (hybrid) fwvc.pos = 0;

            task_check (bytewise_run (pd, &fwv, &fwvc, hybrid, CHANNELS, ref, 0) == FRAMES,
                "19-byte split decodes fully");
            WavpackPushDestroy (pd);
            free (swv);
            free (swvc);
        }

        {
            Bytes fwv = {0}, fwvc = {0};
            fwv.p = (unsigned char *) malloc (wv.n);
            memcpy (fwv.p, wv.p, wv.n);
            fwv.n = wv.n;
            if (hybrid) {
                fwvc.p = (unsigned char *) malloc (wvc.n);
                memcpy (fwvc.p, wvc.p, wvc.n);
                fwvc.n = wvc.n;
            }

            WavpackPushDecoder *pd = WavpackPushCreate (1u << 20, hybrid);
            task_check (bytewise_run (pd, &fwv, &fwvc, hybrid, CHANNELS, ref,
                hybrid ? -1 : 0) == FRAMES,
                "bytewise feed yields every frame");
            WavpackPushDestroy (pd);
            free (fwv.p);
            free (fwvc.p);
        }

        free (wv.p);
        free (wvc.p);
    }
}

// ------------------------------ correction --------------------------------

static void correction_cases (void)
{
    enum { CHANNELS = 6, FRAMES = 257 };
    int32_t pcm [FRAMES * CHANNELS], ref [FRAMES * CHANNELS];
    Bytes wv = {0}, wvc = {0};
    encode_program (CHANNELS, FRAMES, 1, 0, &wv, &wvc, pcm);
    reference_decode (&wv, &wvc, 1, CHANNELS, FRAMES, ref);

    size_t g1wv = first_group_end (&wv);
    size_t g1vc = first_group_end (&wvc);

    // Non-first substream correction arrives late: WV group is complete while
    // only the first physical WVC block (first two channels) is present.

    {
        WavpackPushDecoder *pd = WavpackPushCreate (1u << 20, 1);
        size_t accepted;
        task_check (WavpackPushFeed (pd, 0, wv.p, g1wv, &accepted) == 0 && accepted == g1wv,
            "full first WV group");

        WavpackHeader h0;
        memcpy (&h0, wvc.p, sizeof (h0));
        WavpackLittleEndianToNative (&h0, WavpackHeaderFormat);
        size_t first_block = (size_t) h0.ckSize + 8;
        task_check (first_block < g1vc, "WVC group holds several substream blocks");

        task_check (WavpackPushFeed (pd, 1, wvc.p, first_block, &accepted) == 0 &&
            accepted == first_block, "first WVC substream only");
        int32_t out [16 * CHANNELS];
        uint32_t written = 1;
        task_check (WavpackPushRead (pd, out, 7, &written) == WV_PUSH_NEED_WVC && written == 0,
            "partially closed channel group cannot output");

        task_check (WavpackPushFeed (pd, 1, wvc.p + first_block, g1vc - first_block,
            &accepted) == 0, "remaining WVC substreams arrive late");
        uint64_t got = 0;
        int status = WavpackPushRead (pd, out, 7, &written);
        task_check (status == WV_PUSH_PCM && written == 7, "late WVC unblocks exact PCM");
        for (uint32_t i = 0; i < written; ++i)
            for (int c = 0; c < CHANNELS; ++c)
                task_check (out [i * CHANNELS + c] == ref [(got + i) * CHANNELS + c],
                    "late-correction PCM is lossless");
        WavpackPushDestroy (pd);
    }

    // WVC leads the whole way; no audio may appear before WV catches up.

    {
        WavpackPushDecoder *pd = WavpackPushCreate (1u << 20, 1);
        size_t accepted;
        task_check (WavpackPushFeed (pd, 1, wvc.p, wvc.n, &accepted) == 0 && accepted == wvc.n,
            "WVC fully leads");
        int32_t out [16 * CHANNELS];
        uint32_t written = 7;
        task_check (WavpackPushRead (pd, out, 7, &written) == WV_PUSH_NEED_WV && written == 0,
            "leading WVC alone delivers no PCM");

        size_t pos = 0;
        uint64_t early = 0;
        while (pos < wv.n) {
            size_t want = wv.n - pos < 13 ? wv.n - pos : 13;
            task_check (WavpackPushFeed (pd, 0, wv.p + pos, want, &accepted) == 0, "wv catchup");
            pos += accepted;
            int status = WavpackPushRead (pd, out, 7, &written);
            if (pos < g1wv)
                task_check (status != WV_PUSH_PCM, "no lossy PCM before the WV group closes");
            if (status == WV_PUSH_PCM) {
                for (uint32_t i = 0; i < written; ++i)
                    for (int c = 0; c < CHANNELS; ++c)
                        task_check (out [i * CHANNELS + c] ==
                            ref [(early + i) * CHANNELS + c], "catchup PCM matches reference");
                early += written;
            }
        }

        task_check (WavpackPushFinish (pd, 0) == 0 && WavpackPushFinish (pd, 1) == 0,
            "both lanes finish");
        wv.pos = wv.n;
        wvc.pos = wvc.n;
        int caps [2] = {7, 1};
        task_check (drain_push (pd, &wv, &wvc, 1, CHANNELS, ref, 0, caps, 2, early) == FRAMES,
            "WVC-leading program decodes exactly");
        WavpackPushDestroy (pd);
    }

    // WVC block_index mismatch: the very first group must be rejected, with
    // no audio prefix delivered.

    {
        unsigned char *bad = (unsigned char *) malloc (wvc.n);
        memcpy (bad, wvc.p, wvc.n);
        WavpackHeader h;
        memcpy (&h, bad, sizeof (h));
        WavpackLittleEndianToNative (&h, WavpackHeaderFormat);
        SET_BLOCK_INDEX (h, GET_BLOCK_INDEX (h) + 777);
        WavpackNativeToLittleEndian (&h, WavpackHeaderFormat);
        memcpy (bad, &h, sizeof (h));

        WavpackPushDecoder *pd = WavpackPushCreate (1u << 20, 1);
        size_t accepted;
        task_check (WavpackPushFeed (pd, 0, wv.p, g1wv, &accepted) == 0, "wv before bad wvc");
        task_check (WavpackPushFeed (pd, 1, bad, g1vc, &accepted) == -1,
            "first rejected group: mismatched WVC group 1");
        task_check (WavpackPushGetError (pd) != NULL, "mismatch reason available");
        WavpackPushInfo info;
        WavpackPushGetInfo (pd, &info);
        task_check (info.samples_returned == 0, "prefix delivered before rejected group 1: none");
        WavpackPushDestroy (pd);
        free (bad);
    }

    // Only part of the WVC channel set ever arrives, then WVC finishes:
    // error, never lossy audio.

    {
        WavpackPushDecoder *pd = WavpackPushCreate (1u << 20, 1);
        size_t accepted;
        task_check (WavpackPushFeed (pd, 0, wv.p, g1wv, &accepted) == 0, "wv group present");
        WavpackHeader h0;
        memcpy (&h0, wvc.p, sizeof (h0));
        WavpackLittleEndianToNative (&h0, WavpackHeaderFormat);
        size_t first_block = (size_t) h0.ckSize + 8;
        task_check (WavpackPushFeed (pd, 1, wvc.p, first_block, &accepted) == 0,
            "partial WVC channel set");
        task_check (WavpackPushFinish (pd, 0) == 0 && WavpackPushFinish (pd, 1) == 0,
            "lanes closed around partial WVC");
        int32_t out [16 * CHANNELS];
        uint32_t written = 3;
        int status = WavpackPushRead (pd, out, 7, &written);
        task_check (status == WV_PUSH_ERROR && written == 0, "partial WVC group errors");
        task_check (WavpackPushGetError (pd) != NULL, "partial-WVC reason available");
        WavpackPushInfo info;
        WavpackPushGetInfo (pd, &info);
        task_check (info.samples_returned == 0, "no lossy prefix for an open WVC group");
        WavpackPushDestroy (pd);
    }

    free (wv.p);
    free (wvc.p);
}

// --------------------------------- flow -----------------------------------

static size_t group_offset (Bytes *b, int group_index)
{
    size_t p = 0;
    int seen = 0;

    while (p < b->n) {
        WavpackHeader h;
        memcpy (&h, b->p + p, sizeof (h));
        WavpackLittleEndianToNative (&h, WavpackHeaderFormat);
        size_t end = p + (size_t) h.ckSize + 8;
        if (h.block_samples && (h.flags & FINAL_BLOCK)) {
            if (seen == group_index) return p;
            seen++;
        }
        p = end;
    }

    return (size_t) -1;
}

static void flow_one_program (int frames, size_t limit, size_t *peak_wv, size_t *peak_wvc)
{
    enum { CHANNELS = 6 };
    int32_t pcm [2048 * CHANNELS], ref [2048 * CHANNELS];
    Bytes wv = {0}, wvc = {0};
    task_check (frames <= 2048, "flow program length bounded");
    encode_program (CHANNELS, frames, 1, 0, &wv, &wvc, pcm);
    reference_decode (&wv, &wvc, 1, CHANNELS, frames, ref);

    WavpackPushDecoder *pd = WavpackPushCreate (limit, 1);
    size_t wp = 0, cp = 0, peak_v = 0, peak_c = 0;
    uint64_t delivered = 0;
    int eof_output_seen = 0;
    int caps [3] = {0, 1, 7};
    int cycle = 0, guard = 5000000;
    int32_t pcm_out [16 * CHANNELS];

    // First group of each lane, with neither lane finished: the first audio
    // frames must flow before any EOF is signalled.

    size_t g1wv = first_group_end (&wv), g1vc = first_group_end (&wvc);
    size_t accepted;
    task_check (WavpackPushFeed (pd, 0, wv.p, g1wv, &accepted) == 0 && accepted == g1wv,
        "first WV group staged before EOF");
    task_check (WavpackPushFeed (pd, 1, wvc.p, g1vc, &accepted) == 0 && accepted == g1vc,
        "first WVC group staged before EOF");
    uint32_t written = 0;
    int status = WavpackPushRead (pd, pcm_out, 7, &written);
    task_check (status == WV_PUSH_PCM && written > 0, "first group outputs before either EOF");
    eof_output_seen = 1;
    delivered += written;
    for (uint32_t i = 0; i < written; ++i)
        for (int c = 0; c < CHANNELS; ++c)
            task_check (pcm_out [i * CHANNELS + c] == ref [(delivered - written + i) * CHANNELS + c],
                "pre-EOF PCM matches reference");

    wp = g1wv;
    cp = g1vc;

    for (;;) {
        task_check (--guard > 0, "flow loop terminates");

        for (int lane = 0; lane < 2; ++lane) {
            Bytes *b = lane ? &wvc : &wv;
            size_t *pp = lane ? &cp : &wp;

            if (*pp < b->n) {
                size_t want = b->n - *pp;
                if (want > 37) want = 37;
                size_t acc = 0;
                int rc = WavpackPushFeed (pd, lane, b->p + *pp, want, &acc);
                task_check (rc == 0, "flow feed succeeds");
                task_check (acc <= want, "accepted never exceeds the offered prefix");
                *pp += acc;                 // suffix is simply resent on the next turn
            }
        }

        WavpackPushInfo info;
        task_check (WavpackPushGetInfo (pd, &info) == 1, "format stays known");
        if (info.buffered_wv > peak_v) peak_v = info.buffered_wv;
        if (info.buffered_wvc > peak_c) peak_c = info.buffered_wvc;
        task_check (info.buffered_wv <= limit && info.buffered_wvc <= limit,
            "backpressure keeps each lane within the group limit");
        task_check (info.samples_returned == delivered, "samples_returned tracks handouts only");

        // sentinel: tail samples beyond written must never be touched

        for (int i = 0; i < 16 * CHANNELS; ++i) pcm_out [i] = (int32_t) 0x61234567;
        uint32_t capacity = (uint32_t) caps [cycle++ % 3];
        written = 0;
        status = WavpackPushRead (pd, pcm_out, capacity, &written);

        if (status == WV_PUSH_NEED_OUTPUT) {
            task_check (capacity == 0 && written == 0, "zero capacity stalls without progress");
            for (int i = 0; i < 16 * CHANNELS; ++i)
                task_check (pcm_out [i] == (int32_t) 0x61234567, "zero-capacity buffer untouched");
            continue;
        }

        if (status == WV_PUSH_PCM) {
            task_check (written > 0, "PCM handout non-empty");
            for (uint32_t i = written * CHANNELS; i < 16u * CHANNELS; ++i)
                task_check (pcm_out [i] == (int32_t) 0x61234567, "sentinel tail untouched");
            for (uint32_t i = 0; i < written; ++i)
                for (int c = 0; c < CHANNELS; ++c)
                    task_check (pcm_out [i * CHANNELS + c] ==
                        ref [(delivered + i) * CHANNELS + c], "flow PCM exact");
            delivered += written;
            continue;
        }

        task_check (written == 0, "waiting/done statuses write nothing");

        if (status == WV_PUSH_NEED_WV || status == WV_PUSH_NEED_WVC) {
            int wv_full = wp == wv.n, wvc_full = cp == wvc.n;
            if (wv_full) task_check (WavpackPushFinish (pd, 0) == 0, "deferred wv finish");
            if (wvc_full) task_check (WavpackPushFinish (pd, 1) == 0, "deferred wvc finish");
            continue;
        }

        task_check (status == WV_PUSH_DONE, "flow reaches clean DONE");
        break;
    }

    task_check (eof_output_seen, "audio flowed before end-of-stream");
    task_check (delivered == (uint64_t) frames, "flow delivered the whole program");
    WavpackPushInfo info;
    WavpackPushGetInfo (pd, &info);
    task_check (info.buffered_wv == 0 && info.buffered_wvc == 0, "lanes drained at DONE");
    WavpackPushDestroy (pd);

    *peak_wv = peak_v;
    *peak_wvc = peak_c;
    free (wv.p);
    free (wvc.p);
}

static void flow_cases (void)
{
    // A single oversized feed must be cut short by backpressure instead of
    // buffering the whole program.

    enum { CHANNELS = 6, FRAMES = 257 };
    int32_t pcm [FRAMES * CHANNELS];
    Bytes wv = {0}, wvc = {0};
    encode_program (CHANNELS, FRAMES, 0, 0, &wv, &wvc, pcm);

    {
        const size_t limit = 4096;
        WavpackPushDecoder *pd = WavpackPushCreate (limit, 0);
        size_t accepted = 0;
        task_check (WavpackPushFeed (pd, 0, wv.p, wv.n, &accepted) == 0, "bulk feed call succeeds");
        task_check (accepted < wv.n, "bulk feed is backpressured");
        WavpackPushInfo info;
        WavpackPushGetInfo (pd, &info);
        task_check (info.buffered_wv <= limit, "backpressured buffer at the group bound");
        task_check (info.buffered_wv == accepted, "buffered count is current bytes, not cumulative");

        // while the group is unconsumed every further feed accepts nothing

        size_t again = 7;
        task_check (WavpackPushFeed (pd, 0, wv.p + accepted, 10, &again) == 0 && again == 0,
            "full group blocks successor input");
        WavpackPushDestroy (pd);
    }

    // Programs of very different lengths: the recorded peak retention must be
    // governed by the group limit rather than the program length (no whole-song
    // or whole-group PCM accumulation; only bounded compressed byte groups).

    static const int lengths [3] = {65, 257, 1025};
    size_t peaks [3][2];

    for (int i = 0; i < 3; ++i) {
        flow_one_program (lengths [i], 8192, &peaks [i][0], &peaks [i][1]);
        task_check (peaks [i][0] > 0 && peaks [i][1] > 0, "lanes actually retained data");
        task_check (peaks [i][0] <= 8192 && peaks [i][1] <= 8192, "retention bounded by group limit");
    }

    task_check (peaks [0][0] <= peaks [2][0] * 2 && peaks [2][0] <= 8192,
        "16x longer program does not grow retention with program length");
    task_check (peaks [0][1] <= peaks [2][1] * 2 && peaks [2][1] <= 8192,
        "correction retention also independent of program length");

    // A leading zero-sample metadata block (here a large RIFF wrapper the
    // encoder flushes as its own physical block) is verified, interpreted by
    // the existing block verifier and released immediately: it counts toward
    // the group byte budget but never remains in the buffered byte count.

    {
        enum { C3 = 6, F3 = 193 };
        int32_t p3 [F3 * C3], r3 [F3 * C3];
        Bytes wv = {0}, wvc = {0};
        WavpackConfig config;
        make_pcm (p3, C3, F3);
        memset (&config, 0, sizeof (config));
        config.bits_per_sample = 16;
        config.bytes_per_sample = 2;
        config.num_channels = C3;
        config.channel_mask = (1u << C3) - 1;
        config.sample_rate = 48000;
        config.block_samples = 64;
        WavpackContext *enc = WavpackOpenFileOutput (block_append, &wv, NULL);
        task_check (enc != NULL, "metadata-case encoder opens");
        task_check (WavpackSetConfiguration64 (enc, &config, F3, NULL), "metadata-case configured");
        unsigned char *wrapper = (unsigned char *) malloc (17000);
        memset (wrapper, 'R', 17000);
        task_check (WavpackAddWrapper (enc, wrapper, 17000), "large wrapper metadata added");
        free (wrapper);
        task_check (WavpackPackInit (enc), "metadata-case pack init");
        task_check (WavpackPackSamples (enc, p3, F3), "metadata-case pack");
        task_check (WavpackFlushSamples (enc), "metadata-case flush");
        WavpackCloseFile (enc);

        WavpackHeader mh;
        memcpy (&mh, wv.p, sizeof (mh));
        WavpackLittleEndianToNative (&mh, WavpackHeaderFormat);
        size_t meta_size = (size_t) mh.ckSize + 8;
        task_check (mh.block_samples == 0 && meta_size >= 17000, "encoder emitted a metadata block");

        // a limit that accommodates metadata + one group must accept the stream;
        // a limit below the metadata block must refuse it as a resource error

        WavpackPushDecoder *tight = WavpackPushCreate (meta_size - 8, 0);
        size_t accepted = 0;
        task_check (WavpackPushFeed (tight, 0, wv.p, meta_size, &accepted) == -1,
            "metadata block counted against the group limit");
        task_check (WavpackPushGetError (tight) != NULL, "metadata over-limit reason queryable");
        WavpackPushDestroy (tight);

        WavpackPushDecoder *pd = WavpackPushCreate (1u << 20, 0);
        task_check (WavpackPushFeed (pd, 0, wv.p, wv.n, &accepted) == 0, "metadata program fed");
        task_check (accepted == wv.n, "whole metadata program accepted");
        WavpackPushInfo info;
        task_check (WavpackPushGetInfo (pd, &info) == 0 && info.channels == 0,
            "format stays undetermined until the first audio group is read");

        // one Read activates the first audio group, which determines the format

        int32_t first [16 * C3];
        uint32_t first_written = 0;
        task_check (WavpackPushRead (pd, first, 1, &first_written) == WV_PUSH_PCM &&
            first_written == 1, "first group readable past the metadata block");
        task_check (WavpackPushGetInfo (pd, &info) == 1, "format known past metadata");
        task_check (info.buffered_wv < wv.n && info.buffered_wv <= wv.n - meta_size,
            "released metadata bytes are absent from the buffered count");
        task_check (WavpackPushFinish (pd, 0) == 0, "metadata-case finish");
        reference_decode (&wv, &wvc, 0, C3, F3, r3);
        task_check (first [0] == r3 [0], "first frame matches the reference");
        wv.pos = wv.n;        // nothing left to feed inside the drain engine
        int caps [3] = {1, 7, 3};
        task_check (drain_push (pd, &wv, &wvc, 0, C3, r3, 0, caps, 3, 1) == F3,
            "program with a leading metadata block decodes exactly");
        WavpackPushGetInfo (pd, &info);
        task_check (info.buffered_wv == 0 && info.samples_returned == F3,
            "metadata lane fully drained");
        WavpackPushDestroy (pd);
        free (wv.p);
    }

    // Two instances interleaved on the same program must keep fully
    // independent lanes, counts and decode positions (no shared mutable state).

    {
        enum { C2 = 6, F2 = 129 };
        int32_t p2 [F2 * C2], r2 [F2 * C2];
        Bytes a_wv = {0}, a_wvc = {0};
        encode_program (C2, F2, 1, 0, &a_wv, &a_wvc, p2);
        reference_decode (&a_wv, &a_wvc, 1, C2, F2, r2);

        WavpackPushDecoder *x = WavpackPushCreate (1u << 20, 1);
        WavpackPushDecoder *y = WavpackPushCreate (1u << 20, 1);
        size_t accepted;

        task_check (WavpackPushFeed (x, 0, a_wv.p, 100, &accepted) == 0 && accepted == 100,
            "instance x wv prefix");
        task_check (WavpackPushFeed (y, 1, a_wvc.p, 250, &accepted) == 0 && accepted == 250,
            "instance y wvc prefix");
        task_check (WavpackPushFeed (x, 1, a_wvc.p, 70, &accepted) == 0 && accepted == 70,
            "instance x wvc prefix");

        WavpackPushInfo ix, iy;
        task_check (WavpackPushGetInfo (x, &ix) == 0, "x still waiting for a group");
        task_check (WavpackPushGetInfo (y, &iy) == 0, "y still waiting for a group");
        task_check (ix.buffered_wv == 100 && ix.buffered_wvc == 70, "x lane buffers independent");
        task_check (iy.buffered_wv == 0 && iy.buffered_wvc == 250, "y lane buffers independent");

        // each instance needs its own cursor because it prefed different amounts

        Bytes x_wv = a_wv, x_wvc = a_wvc, y_wv = a_wv, y_wvc = a_wvc;
        x_wv.pos = 100; x_wvc.pos = 70;
        y_wv.pos = 0;   y_wvc.pos = 250;
        int caps [2] = {7, 1};
        task_check (drain_push (x, &x_wv, &x_wvc, 1, C2, r2, 1, caps, 2, 0) == F2,
            "interleaved instance x decodes the full program");
        task_check (drain_push (y, &y_wv, &y_wvc, 1, C2, r2, 1, caps, 2, 0) == F2,
            "interleaved instance y decodes the full program");

        WavpackPushGetInfo (x, &ix);
        WavpackPushGetInfo (y, &iy);
        task_check (ix.samples_returned == F2 && iy.samples_returned == F2,
            "both instances account their own frames");
        WavpackPushDestroy (x);
        WavpackPushDestroy (y);
        free (a_wv.p);
        free (a_wvc.p);
    }

    free (wv.p);
    free (wvc.p);
}

// ------------------------------- terminal ---------------------------------

static void terminal_cases (void)
{
    enum { CHANNELS = 6, FRAMES = 257 };
    int32_t pcm [FRAMES * CHANNELS], ref [FRAMES * CHANNELS];

    // Unknown total length still reaches DONE once both lanes close.

    {
        Bytes wv = {0}, wvc = {0};
        encode_program (CHANNELS, FRAMES, 1, 1, &wv, &wvc, pcm);
        reference_decode (&wv, &wvc, 1, CHANNELS, FRAMES, ref);
        WavpackPushDecoder *pd = WavpackPushCreate (1u << 20, 1);
        size_t accepted;
        task_check (WavpackPushFeed (pd, 0, wv.p, wv.n, &accepted) == 0 && accepted == wv.n,
            "unknown-length wv fed");
        task_check (WavpackPushFeed (pd, 1, wvc.p, wvc.n, &accepted) == 0 && accepted == wvc.n,
            "unknown-length wvc fed");
        task_check (WavpackPushFinish (pd, 0) == 0, "first finish");
        task_check (WavpackPushFinish (pd, 0) == 0, "repeated finish is allowed");
        task_check (WavpackPushFinish (pd, 1) == 0, "wvc finish");
        task_check (WavpackPushFinish (pd, 1) == 0, "repeated wvc finish");
        wv.pos = wv.n;
        wvc.pos = wvc.n;
        int caps [2] = {7, 3};
        task_check (drain_push (pd, &wv, &wvc, 1, CHANNELS, ref, 0, caps, 2, 0) == FRAMES,
            "unknown-length program fully decoded");
        uint32_t written = 5;
        int32_t out [CHANNELS];
        task_check (WavpackPushRead (pd, out, 1, &written) == WV_PUSH_DONE && written == 0,
            "DONE is sticky and writes nothing");
        task_check (WavpackPushRead (pd, out, 1, &written) == WV_PUSH_DONE, "DONE repeats");
        WavpackPushDestroy (pd);
        free (wv.p);
        free (wvc.p);
    }

    // Half-header and half-body truncations on both lanes.

    for (int hybrid = 0; hybrid <= 1; ++hybrid) {
        Bytes wv = {0}, wvc = {0};
        encode_program (CHANNELS, FRAMES, hybrid, 0, &wv, &wvc, pcm);

        static const size_t cuts [2] = {19, 0};
        for (int ci = 0; ci < 2; ++ci) {
            size_t cut = ci ? wv.n / 2 : cuts [ci];
            WavpackPushDecoder *pd = WavpackPushCreate (1u << 20, hybrid);
            size_t accepted;
            task_check (WavpackPushFeed (pd, 0, wv.p, cut, &accepted) == 0 && accepted == cut,
                "truncated wv prefix stored");
            if (hybrid) {
                size_t ccut = wvc.n / 2;
                task_check (WavpackPushFeed (pd, 1, wvc.p, ccut, &accepted) == 0,
                    "truncated wvc prefix stored");
            }
            task_check (WavpackPushFinish (pd, 0) == 0, "truncated wv closed");
            if (hybrid) task_check (WavpackPushFinish (pd, 1) == 0, "truncated wvc closed");
            uint32_t written = 1;
            int32_t out [16 * CHANNELS];
            int status = WV_PUSH_PCM;
            while (status == WV_PUSH_PCM)
                status = WavpackPushRead (pd, out, 7, &written);
            task_check (status == WV_PUSH_ERROR, "truncated stream enters ERROR");
            task_check (WavpackPushGetError (pd) != NULL, "truncation reason queryable");
            task_check (WavpackPushFeed (pd, 0, wv.p, 1, &accepted) == -1,
                "sticky ERROR rejects further feeds");
            task_check (WavpackPushRead (pd, out, 7, &written) == WV_PUSH_ERROR,
                "sticky ERROR rejects further reads");
            WavpackPushDestroy (pd);
        }

        free (wv.p);
        free (wvc.p);
    }

    // CRC/structure corruption inside group 3: groups 1-2 (128 frames) form
    // the delivered prefix, group 3 is the first rejected group.

    {
        Bytes wv = {0}, wvc = {0};
        encode_program (CHANNELS, FRAMES, 0, 0, &wv, &wvc, pcm);
        reference_decode (&wv, &wvc, 0, CHANNELS, FRAMES, ref);

        size_t g3 = group_offset (&wv, 2);
        task_check (g3 != (size_t) -1, "third group exists");
        wv.p [g3 + 40] ^= 0x40;       // corrupt inside the first block of group 3

        WavpackPushDecoder *pd = WavpackPushCreate (1u << 20, 0);
        size_t wp = 0, accepted;
        int32_t out [16 * CHANNELS];
        uint64_t delivered = 0;
        int saw_error = 0, guard = 1000000;

        for (;;) {
            task_check (--guard > 0, "corruption loop terminates");
            if (wp < wv.n) {
                size_t want = wv.n - wp < 17 ? wv.n - wp : 17;
                int rc = WavpackPushFeed (pd, 0, wv.p + wp, want, &accepted);
                if (rc == -1) { saw_error = 1; break; }
                wp += accepted;
            }
            uint32_t written = 0;
            int status = WavpackPushRead (pd, out, 7, &written);
            if (status == WV_PUSH_PCM) {
                for (uint32_t i = 0; i < written; ++i)
                    for (int c = 0; c < CHANNELS; ++c)
                        task_check (out [i * CHANNELS + c] ==
                            ref [(delivered + i) * CHANNELS + c], "prefix before corruption exact");
                delivered += written;
            }
            else if (status == WV_PUSH_ERROR) {
                saw_error = 1;
                break;
            }
            else {
                task_check (status == WV_PUSH_NEED_WV || status == WV_PUSH_NEED_OUTPUT,
                    "waiting for more corrupted stream bytes");
                if (wp == wv.n) {
                    task_check (WavpackPushFinish (pd, 0) == 0, "close corrupted stream");
                    status = WavpackPushRead (pd, out, 7, &written);
                    if (status == WV_PUSH_ERROR) { saw_error = 1; break; }
                    if (status == WV_PUSH_PCM) delivered += written;
                }
            }
        }

        task_check (saw_error, "first rejected group: corrupted group 3");
        task_check (delivered == 128, "prefix delivered before group 3: groups 1 and 2 only");
        task_check (WavpackPushGetError (pd) != NULL, "corruption reason queryable");
        WavpackPushDestroy (pd);
        free (wv.p);
    }

    // An unmatched trailing correction group must not be ignored: once the WV
    // program is fully delivered and both lanes are closed, the extra WVC bytes
    // force an error rather than a premature DONE.

    {
        Bytes wv = {0}, wvc = {0};
        encode_program (CHANNELS, FRAMES, 1, 0, &wv, &wvc, pcm);
        reference_decode (&wv, &wvc, 1, CHANNELS, FRAMES, ref);

        size_t g1vc = first_group_end (&wvc);
        Bytes extra = {0};
        extra.n = wvc.n + g1vc;
        extra.p = (unsigned char *) malloc (extra.n);
        memcpy (extra.p, wvc.p, wvc.n);
        memcpy (extra.p + wvc.n, wvc.p, g1vc);     // one WVC group duplicated at the tail

        WavpackPushDecoder *pd = WavpackPushCreate (1u << 20, 1);
        size_t wp = 0, cp = 0, accepted;
        int32_t out [16 * CHANNELS];
        uint64_t delivered = 0;
        int guard = 1000000;

        // feed both lanes completely, resending backpressured suffixes after
        // draining whatever PCM the decoder can currently release

        while (wp < wv.n || cp < extra.n) {
            task_check (--guard > 0, "extra-wvc feed loop terminates");

            if (wp < wv.n) {
                size_t want = wv.n - wp;
                task_check (WavpackPushFeed (pd, 0, wv.p + wp, want, &accepted) == 0,
                    "wv program fed");
                wp += accepted;
            }

            if (cp < extra.n) {
                size_t want = extra.n - cp;
                task_check (WavpackPushFeed (pd, 1, extra.p + cp, want, &accepted) == 0,
                    "wvc with trailing duplicate fed");
                cp += accepted;
            }

            uint32_t written = 0;
            int st = WavpackPushRead (pd, out, 7, &written);
            if (st == WV_PUSH_PCM) delivered += written;
        }

        task_check (WavpackPushFinish (pd, 0) == 0, "wv finished");
        task_check (WavpackPushFinish (pd, 1) == 0, "wvc finished");

        int status;
        do {
            uint32_t written = 0;
            status = WavpackPushRead (pd, out, 7, &written);
            if (status == WV_PUSH_PCM) delivered += written;
            task_check (--guard > 0, "extra-wvc loop terminates");
        } while (status == WV_PUSH_PCM);

        task_check (status == WV_PUSH_ERROR, "extra correction group blocks DONE");
        task_check (WavpackPushGetError (pd) != NULL, "extra-wvc reason queryable");
        task_check (delivered == FRAMES, "full audio prefix delivered before the tail error");
        WavpackPushDestroy (pd);
        free (wv.p);
        free (wvc.p);
        free (extra.p);
    }

    // Resource limit: a group larger than max_group_bytes is a clear error,
    // never an endless zero-accepted wait.

    {
        Bytes wv = {0}, wvc = {0};
        encode_program (CHANNELS, FRAMES, 0, 0, &wv, &wvc, pcm);
        WavpackPushDecoder *pd = WavpackPushCreate (64, 0);
        size_t accepted = 0;
        task_check (WavpackPushFeed (pd, 0, wv.p, wv.n, &accepted) == -1,
            "oversized group raises a resource error");
        task_check (WavpackPushGetError (pd) != NULL, "resource reason queryable");
        WavpackPushDestroy (pd);
        task_check (WavpackPushCreate (31, 0) == NULL, "limit below 32 rejected at create");
        task_check (WavpackPushCreate (1024, 2) == NULL, "require_wvc outside 0/1 rejected");
        free (wv.p);
    }

    // Illegal arguments never damage a valid object: counters clear, work continues.

    {
        Bytes wv = {0}, wvc = {0};
        encode_program (CHANNELS, FRAMES, 0, 0, &wv, &wvc, pcm);
        reference_decode (&wv, &wvc, 0, CHANNELS, FRAMES, ref);
        WavpackPushDecoder *pd = WavpackPushCreate (1u << 20, 0);
        size_t accepted = 99;

        task_check (WavpackPushFeed (NULL, 0, wv.p, 4, &accepted) == -1, "null decoder feed rejected");
        task_check (WavpackPushFeed (pd, 7, wv.p, 4, &accepted) == -1 && accepted == 0,
            "bad lane rejected with accepted cleared");
        task_check (WavpackPushFeed (pd, 0, NULL, 4, &accepted) == -1 && accepted == 0,
            "null data rejected with accepted cleared");
        task_check (WavpackPushFeed (pd, 0, wv.p, 4, NULL) == -1, "null accepted pointer rejected");
        task_check (WavpackPushFeed (pd, 1, wv.p, 4, &accepted) == -1 && accepted == 0,
            "WVC rejected on lossless decoder, object intact");
        task_check (WavpackPushFinish (pd, 9) == -1, "bad finish lane rejected");
        task_check (WavpackPushFinish (NULL, 0) == -1, "null finish rejected");

        uint32_t written = 99;
        task_check (WavpackPushRead (pd, NULL, 4, &written) == -1 && written == 0,
            "null PCM rejected with written cleared");
        task_check (WavpackPushRead (pd, NULL, 0, NULL) == -1, "null written pointer rejected");
        task_check (WavpackPushGetInfo (pd, NULL) == -1, "null info rejected");
        task_check (WavpackPushGetError (pd) == NULL, "no sticky error after bad arguments");
        WavpackPushDestroy (NULL);       // must be a no-op

        wv.pos = 0;
        int caps [3] = {1, 7, 2};
        task_check (drain_push (pd, &wv, &wvc, 0, CHANNELS, ref, 1, caps, 3, 0) == FRAMES,
            "legal use continues after every rejected argument");
        WavpackPushDestroy (pd);
        free (wv.p);
        free (wvc.p);
    }
}

void push_cases (const char *group)
{
    if (!strcmp (group, "fragment"))
        fragment_cases ();
    else if (!strcmp (group, "correction"))
        correction_cases ();
    else if (!strcmp (group, "flow"))
        flow_cases ();
    else if (!strcmp (group, "terminal"))
        terminal_cases ();
}
